mapper.select:
select cs.id as id, cs.Create_Uid as createUid, cs.Create_Uname as createUname, cs.Create_Time as createTime, cs.State as state, cs.State_Time as stateTime, cs.Con_Id as conId, con.Con_Name as conName, con.Con_Code as conCode, pany.C_Name as conPartyBName, pp.P_Name as pName, cs.Cs_Money as csMoney, cs.Cs_Settlemen_Downgrading as csSettlemenDowngrading, cs.Cs_Payment_Method as csPaymentMethod from Contract_Statistics cs left join Con_Contract con on cs.Con_Id = con.Con_Id left join Sys_Company pany on con.Con_Party_B_Id = pany.C_Id left join Pre_Project pp on con.Con_Project_Id = pp.P_Id
con.Con_Approval_State = 7 and con.Con_Type NOT IN ('07','0701','0702','0703')
and cs.Con_Id = #{params.conId}
and con.Con_Project_Id = #{params.pId}
and con.Con_Project_Id = #{params.conProjectId}
and con.Con_Name like concat('%', #{params.conName}, '%')
and con.con_Code like concat('%', #{params.conCode}, '%')
and con.Con_Party_B_Id = #{params.conPartyBId}
and likeCname(#{params.conPartyBName}, pany.C_Id)=true
and pany.C_Name like concat('%', #{params.conPartyBName}, '%')
and pp.P_Name like concat('%', #{params.conProjectName}, '%')
order by cs.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by cs.Create_Time desc
